  function live(packet) {

    if(blockedPacket(packet)||packet?.type!=='event'||packet?.payload?.table!=='messages')return;
    const p=packet.payload;
    if(p.operation==='DELETE') deletion(p.old_record?.id);
    else if(p.record) remember(p.record);
  }
  function replaceText(text) {
    if(!cfg.autoedit||typeof text!=='string') return text;
    let result=text;
    for(const rule of cfg.rules.slice(0,40)) {
      if(rule.find&&rule.enabled!==false) result=result.split(rule.find).join(rule.replace||'');
    }
    return result;
  }
