    if(backend&&method==='POST'){try{requestBody=JSON.parse(await new Request(input,init).clone().text());}catch{}}
    if(backend&&cfg.blockMuted&&/\/rpc\/channel_messages(?:_since)?$/.test(url.pathname)&&mutedChannel(requestBody?.cid))return new window.Response(JSON.stringify({messages:[],profiles:[],reactions:[]}),{status:200,headers:{'content-type':'application/json'}});
    if(backend&&url.pathname==='/rest/v1/messages'&&method==='GET'){const id=url.searchParams.get('channel_id')?.replace(/^eq\./,'');if(cfg.blockMuted&&mutedChannel(id))return new window.Response('[]',{status:200,headers:{'content-type':'application/json'}});}
    if(backend&&method==='POST'&&url.pathname==='/rest/v1/messages'&&requestBody){let changed=false;
      for(const row of Array.isArray(requestBody)?requestBody:[requestBody])if(row?.author_id===uid&&typeof row.content==='string'){const next=nativeMarkdown(replaceText(row.content));if(next!==row.content){row.content=next;changed=true;}const pending=state()?.messages?.[row.channel_id]?.find(m=>m.id===row.id),name=pending?.attachment_path?.split('/').pop();if(name?.startsWith('yappy-emoji-')){Object.assign(row,{attachment_name:name.slice(0,200),attachment_width:32,attachment_height:32});changed=true;}}
      if(changed){const request=new Request(input,init);input=new Request(request,{body:JSON.stringify(requestBody)});init=undefined;}
    }
    const response=await nativeFetch.call(this,input,init);
