  const rtSockets=new Set();
  const NativeWS=window.WebSocket;
  const WrappedWS=new Proxy(NativeWS,{construct(target,args,newTarget){
    const socket=Reflect.construct(target,args,newTarget);let host='';try{host=new URL(String(args[0]),location.href).hostname;}catch{}
    if(host==='rt.yapper.website'){
      rtSockets.add(socket);socket.addEventListener('close',()=>rtSockets.delete(socket),{once:true});const send=socket.send.bind(socket);
      socket.send=function(value){if(typeof value==='string')try{const packet=JSON.parse(value);if(cfg.experiments.silentTyping&&packet.type==='typing')return;if(cfg.blockMuted&&packet.type==='subscribe'&&Array.isArray(packet.topics)){packet.topics=packet.topics.filter(t=>!mutedTopic(t));if(!packet.topics.length)return;value=JSON.stringify(packet);}}catch{}return send(value);};
      socket.addEventListener('message',e=>{if(typeof e.data!=='string')return;try{const packet=JSON.parse(e.data);if(blockedPacket(packet)){e.stopImmediatePropagation();return;}live(packet);}catch{}},true);
    }return socket;
  }});window.WebSocket=WrappedWS;
  let pruning=false,lastMuteSignature='';
  function mutedTopic(topic){if(typeof topic!=='string')return false;return topic.startsWith('chan:')?mutedChannel(topic.slice(5)):topic.startsWith('server:')?!!state()?.mutedServers?.[topic.slice(7)]:false;}
  function syncMuteTopics(){
    if(!api)return;const s=state(),key=JSON.stringify([cfg.blockMuted,s.muted,s.mutedServers]);if(key===lastMuteSignature)return;const first=!lastMuteSignature;lastMuteSignature=key;
    const all=api.chat.wantedTopics?.();if(all&&api.rt?.setTopics)api.rt.setTopics([...all].filter(t=>!cfg.blockMuted||!mutedTopic(t)));
    pruneMuted();if(!first&&s.activeChannelId&&!mutedChannel(s.activeChannelId)&&!s.messages?.[s.activeChannelId]?.length)reloadChannel(s.activeChannelId);
  }
  async function reloadChannel(id){try{const {data,error}=await api.db.rpc('channel_messages',{cid:id,before:null,lim:50});if(error||mutedChannel(id))return;if(data?.profiles&&api.store.mergeProfiles)api.store.mergeProfiles(data.profiles);if(data?.messages)api.store.setState(s=>({messages:{...s.messages,[id]:data.messages}}));}catch{}}
  async function toggleChannelMute(channel){
    if(api.chat.toggleMute)await api.chat.toggleMute(channel.id);else{const old=!!state().muted?.[channel.id],value=!old;api.store.setState(s=>({muted:{...s.muted,[channel.id]:value}}));const {error}=await api.db.rpc('set_muted',{cid:channel.id,mute:value});if(error){api.store.setState(s=>({muted:{...s.muted,[channel.id]:old}}));throw error;}}
    syncMuteTopics();schedulePaint();
  }

  async function bridge() {
    const tp=window.TURBOPACK;
    if(!tp?.push||Array.isArray(tp)) return false;
    if(!ctx) {
      const id='yappy.bridge.'+crypto.randomUUID();
      tp.push(['/yappy-local-bridge.js',id,c=>{ctx=c;}]);
      await tp.push({otherChunks:[],runtimeModuleIds:[id]});
    }
    if(!ctx?.c) return false;
    const modules=[...ctx.c.values()].flatMap(m=>[m.exports,m.namespaceObject]).filter(Boolean);
    const find=predicate=>modules.find(m=>{try{return predicate(m);}catch{return false;}});
    const store=find(m=>m.getState&&m.setState&&m.useStore?.subscribe);
    const chat=find(m=>m.openChannel&&m.toggleServerMute&&m.openDmWith);
    const dbModule=find(m=>typeof m.sb==='function');
    const servers=find(m=>m.discoverServers&&m.joinPublicServer&&m.openServer);
    const media=find(m=>m.publicUrl&&m.uploadImage);
    const flags=find(m=>m.setOverride&&m.isFlagOn);
    if(!store||!chat||!dbModule||!servers) return false;
    api={store,chat,servers,media,flags,rt:find(m=>m.setTopics&&m.sendTypingRt),voice:find(m=>m.toggleMute&&m.toggleDeafen&&m.joinVoice),db:dbModule.sb()};
    connected=true;
    account(store.getState().userId||null);
    for(const rows of Object.values(state().messages||{})) rows.forEach(remember);
    store.useStore.subscribe((s,prev)=>{
      account(s.userId||null);if(s.activeChannelId!==prev.activeChannelId||s.activeServerId!==prev.activeServerId||s.settingsAt!==prev.settingsAt||s.profiles!==prev.profiles||s.emojis!==prev.emojis||s.voice!==prev.voice)forceStructure=true;syncMuteTopics();if(s.activeServerId!==prev.activeServerId)applyTheme();
      if(selfOpen && (s.activeChannelId!==prev.activeChannelId || s.activeServerId!==prev.activeServerId || s.showDiscovery!==prev.showDiscovery)) closeSelf();
      if(!s.settingsAt && nativeMode){nativeMode=false;deactivateNative();}
      if(s.profiles!==prev.profiles&&selfOpen){const a=s.profiles[uid],b=prev.profiles[uid];if(JSON.stringify([a?.username,a?.display_name,a?.avatar_path])!==JSON.stringify([b?.username,b?.display_name,b?.avatar_path]))renderSelf();}
      if(s.userId && !prev.userId) autoJoinCommunity();
      if(s.messages!==prev.messages && (cfg.history||cfg.keepDeleted)) {
        for(const [cid,rows] of Object.entries(s.messages)) if(rows!==prev.messages[cid]) rows.forEach(remember);
      }
      if(s.messages!==prev.messages||s.activeChannelId!==prev.activeChannelId||s.userId!==prev.userId||s.emojis!==prev.emojis||s.activeServerId!==prev.activeServerId||s.voiceMembers!==prev.voiceMembers||s.voice!==prev.voice) schedulePaint();
    });
    applyExperiments();schedulePaint();if(uid)autoJoinCommunity();
    return true;
  }
  const el=(tag,attrs={},...kids)=>{
    const node=document.createElement(tag);
    for(const [k,v] of Object.entries(attrs)){
      if(k.startsWith('on'))node.addEventListener(k.slice(2).toLowerCase(),v);
      else if(k==='class')node.className=v;
      else if(k in node)node[k]=v;
      else node.setAttribute(k,v);
    }
    for(const child of kids.flat())if(child!=null)node.append(child instanceof Node?child:document.createTextNode(String(child)));
    return node;
  };
  const paragraph=text=>el('p',{},text);
  const input=(value='',placeholder='')=>el('input',{value,placeholder});
  const card=(title,...kids)=>el('section',{class:'card'},el('h3',{},title),...kids);
  const field=(label,node)=>el('label',{class:'field'},el('span',{},label),node);
  const row=(...kids)=>el('div',{class:'row'},...kids);
  function button(text,fn,kind=''){
    return el('button',{type:'button',class:kind,onclick:async e=>{
      const node=e.currentTarget;node.disabled=true;
      try{await fn(e);}catch(error){toast(error?.message||String(error));}finally{node.disabled=false;}
    }},text);
  }
  function toast(text){
    const old=document.querySelector('[data-yappy-toast]');old?.remove();
    const node=el('div',{'data-yappy-toast':'','data-yappy-owned':'',role:'status'},text);
    document.body?.append(node);setTimeout(()=>node.remove(),5500);
  }
  function requireAccount(){
    if(!connected)throw Error('Yappy is still connecting. Reload Yapper if this continues.');
    if(!uid)throw Error('Sign in to Yapper first.');
    if(state().siteBan)throw Error('This account is restricted by Yapper.');
  }
  function download(name,value,type='application/json'){
    const blob=value instanceof Blob?value:new Blob([typeof value==='string'?value:JSON.stringify(value,null,2)],{type});
    const url=URL.createObjectURL(blob);el('a',{href:url,download:name}).click();setTimeout(()=>URL.revokeObjectURL(url),3000);
  }
  async function autoJoinCommunity(){
    if(!uid||state()?.siteBan||joining||lastJoinAttempt===uid)return;
    const user=uid,key='yappy:community:'+user;
    if(read(key,false))return;
    joining=true;lastJoinAttempt=user;
    try{
      const invite=await api.servers.getInvite?.(COMMUNITY);
      if(uid!==user)return;
      const sid=invite?.server_id||invite?.id;
      if(!sid||!state().servers[sid]){
        if(!api.servers.joinServer)throw Error('Invite joining is unavailable.');
        await api.servers.joinServer(COMMUNITY);
        if(uid!==user)return;
        await api.servers.loadServers?.();
      }
      storage(key,true);toast('Welcome to the Yappy community.');
    }catch(e){toast('Could not join the Yappy community: '+(e.message||e));}finally{joining=false;}
  }
  function toggle(label,key,description=''){
    const node=el('input',{type:'checkbox',role:'switch','aria-label':label,checked:!!cfg[key],onchange:e=>{
      cfg[key]=e.target.checked;if(key==='transparency'&&cfg[key])cfg.theme=true;saveSettings();
      if(key==='selfchat'&&!cfg.selfchat)closeSelf();
      if(key==='stickers'&&!cfg.stickers)closePicker();
    }});
    return el('label',{class:'switch-row'},el('span',{},el('b',{},label),description?el('small',{},description):null),node);
  }
