    if(bioPendingKey===key)return;clearTimeout(bioTimer);bioPendingKey=key;const user=uid,delay=Math.max(350,60000-(Date.now()-lastBioWrite),bioRetryAt-Date.now());bioTimer=setTimeout(async()=>{bioPendingKey='';if(!cfg.bioPresence.enabled||uid!==user||bioBusy)return;const media=currentMedia();if(profile().bio!==cfg.bioPresence.last&&profile().bio!==cfg.bioPresence.base)cfg.bioPresence.base=profile().bio||'';const text=bioLine(media,cfg.bioPresence.base);if(text===(profile().bio||'')){lastBioSignature=key;updateBioStatus();return;}bioBusy=true;try{await writeBio(text);lastBioSignature=key;bioRetryAt=0;}catch(e){bioError=e.message||'Bio update failed';bioRetryAt=Date.now()+30000;toast('BioPresence: '+bioError+" or retrying in 30 seconds");}finally{bioBusy=false;updateBioStatus();if(cfg.bioPresence.enabled&&bioError)setTimeout(syncBio,30000);}},delay);
