async function uploadThemeImage(file,generate){
  if(!file)return;if(!/^(?:image\/(?:png|jpeg|webp|gif|avif)|video\/[a-z0-9.+-]+)$/.test(file.type))throw Error('Choose an image or video');if(generate&&file.type.startsWith('video/'))throw Error('Choose a still image for a palette');if(!file.type.startsWith('video/')){const duration=await wallpaperDuration(file);if(duration>20.001)throw Error('Animated wallpapers must be 20 seconds or shorter');}else await wallpaperDuration(file);if(file.type==='image/gif')file=await loopWallpaperGIF(file);if(!file.type.startsWith('video/')&&file.size>25*1024*1024)throw Error('Choose an image smaller than 25 MB');
  if(generate&&cfg.market?.activeTheme)await clearMarketTheme(false);const palette=generate?await imagePalette(file):null;if(!generate&&!file.type.startsWith('video/')){const img=new Image(),url=URL.createObjectURL(file);try{img.src=url;await img.decode();}finally{URL.revokeObjectURL(url);}}
  const key='theme-background:'+crypto.randomUUID();if(!await keepBlob(key,file))throw Error('Could not save this image');const old=effectiveTheme().backgroundAsset;
  setActiveWallpaper({...palette,theme:true,transparency:true,text:'#f5f5fa',wallpaperDim:Math.max(.48,Number(effectiveTheme().wallpaperDim)||0),panelOpacity:Math.min(.72,Number(effectiveTheme().panelOpacity)||.72),backgroundAsset:key,backgroundName:file.name});
  cfg.typography.matchAccent=false;cfg.typography.color='#f5f5fa';const previous=wallpaperURL;wallpaperKey=key;++wallpaperTask;wallpaperURL=URL.createObjectURL(file);wallpaperVideoURL=file.type.startsWith('video/')?wallpaperURL:'';saveSettings();render();if(previous)URL.revokeObjectURL(previous);if(old&&old!==key)deleteThemeImage(old);toast(generate?'Image theme ready':'Background updated');
}
