    const height=Math.max(110,y+pad);if(height>4200)throw Error("Message image is too tall or shorten the cards");canvas.width=width*scale;canvas.height=Math.ceil(height)*scale;ctx.scale(scale,scale);if(!options.transparent){ctx.fillStyle=surface;ctx.fillRect(0,0,width,height);}for(const op of ops.filter(o=>o.type==='card')){ctx.fillStyle=surface+'dd';ctx.beginPath();ctx.roundRect(pad,op.start,width-pad*2,op.end-op.start,10);ctx.fill();ctx.fillStyle=op.color;ctx.fillRect(pad,op.start,4,op.end-op.start);}for(const op of ops){if(op.type==='text'){ctx.fillStyle=ink;ctx.font=`${op.weight} ${op.size}px ${font}`;op.lines.forEach((line,i)=>ctx.fillText(line,op.x,op.y+op.size+i*op.size*1.45,width-op.x-pad));}else if(op.type==='image'){ctx.drawImage(op.bitmap,pad+12,op.y,width-pad*2-24,op.height);}else if(op.type==='button'){ctx.fillStyle=options.color;ctx.beginPath();ctx.roundRect(op.x,op.y,op.w,32,6);ctx.fill();ctx.fillStyle=foreground(options.color);ctx.font=`600 13px ${font}`;ctx.fillText(op.button.label,op.x+8,op.y+21,op.w-16);}}return await new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(Error('Could not render image')),'image/png'));
