async function packageDisable(entry){const runtime=packageRuntimes.get(entry.id);if(runtime){runtime.cancelled=true;for(const cleanup of runtime.cleanup.reverse())try{await cleanup();}catch(error){console.warn('[Yappy] Plugin cleanup failed',entry.id,error);}packageRuntimes.delete(entry.id);}packageSettingAttrs(entry,true);entry.enabled=false;storage(KEY,cfg);marketViewRefresh?.();}
