const yapmodDefaults={"dark":{"bg-rail":"#141519","bg-side":"#1b1c21","bg-main":"#222329","bg-elev":"#2b2c33","bg-hover":"#2f3038","bg-active":"#383944","bg-input":"#2d2e36","bg-float":"#1b1c21","text":"#ececf1","text-muted":"#9c9daa","text-faint":"#6e6f7b","border":"#ffffff12","accent":"#ff6b4a","accent-hover":"#ff5a35","accent-soft":"#ff6b4a29","on-accent":"#ffffff","danger":"#f2555a","success":"#3fcf82","warning":"#f5b544","radius":"10px","shadow":"0 10px 40px #00000073"},"light":{"bg-rail":"#e3e5e8","bg-side":"#f2f3f5","bg-main":"#ffffff","bg-elev":"#ebedef","bg-hover":"#e6e7ea","bg-active":"#d7d9de","bg-input":"#ebedef","bg-float":"#ffffff","text":"#1d1f23","text-muted":"#5b5d66","text-faint":"#8b8d96","border":"#00000017","accent":"#ff6b4a","accent-hover":"#ff5a35","accent-soft":"#ff6b4a24","on-accent":"#ffffff","danger":"#f2555a","success":"#3fcf82","warning":"#f5b544","radius":"10px","shadow":"0 10px 34px #00000029"}};
function prepareThemeCSS(css){return css.replace(/--(bg-(?:rail|side|main|elev|hover|active|input|float)|text(?:-muted|-faint)?|border|accent(?:-hover|-soft)?|on-accent|danger|success|warning|radius|shadow)\s*:\s*([^;{}]+)(;|(?=\}))/g,(all,key,value)=>all.replace(/;?$/, ';')+'--yappy-import-'+key+':'+value+';');}
