function updateMarketTheme(){if(!marketThemeRuntime)return;const {entry,style,mapping,bundle}=marketThemeRuntime;document.documentElement.dataset.yapmodTheme=entry.manifest.id;document.documentElement.dataset.yapmodMode=themeMode(entry);if(!style.isConnected)document.documentElement.append(style);if(!mapping.isConnected)document.documentElement.append(mapping);const computed=getComputedStyle(document.documentElement),palette={};for(const [token,key]of [['bg-main','background'],['bg-elev','surface'],['accent','accent'],['text','text']]){const direct=new RegExp('--'+token+'\\s*:').test(bundle.css),value=computed.getPropertyValue(direct?'--yappy-import-'+token:'--ym-'+token).trim();if(value&&(direct||new RegExp('--ym-'+token+'\\s*:').test(bundle.css))){const colour=computedColour(value);if(colour)palette[key]=colour;}}marketThemePalette=palette;if(cfg.useServerAccent){const theme=effectiveTheme();mapping.textContent=mapYapmodTheme(entry,bundle.css)+':root[data-yapmod-theme][data-yapmod-mode][data-yappy-ready]{--accent:'+themeColor(theme.accent)+'!important;--text:'+effectiveTextColor(theme)+'!important;}';}else mapping.textContent=mapYapmodTheme(entry,bundle.css);}
