async function clearMarketTheme(refresh=true,keepRequest=false){if(!keepRequest)marketThemeRequest++;marketThemeRuntime?.style.remove();marketThemeRuntime?.mapping.remove();marketThemeRuntime=null;marketThemePalette=null;cfg.market.activeTheme='';document.documentElement.removeAttribute('data-yapmod-theme');document.documentElement.removeAttribute('data-yapmod-mode');if(refresh){applyTheme();styleBranding();applyClockTheme();storage(KEY,cfg);marketViewRefresh?.();}}
