function publicSourceURL(value){let url;try{url=new URL(value);}catch{throw Error('Enter a full HTTPS repository or catalog URL');}if(url.protocol!=='https:'||url.username||url.password||/^(localhost|127\.|10\.|192\.168\.|169\.254\.|0\.|\[)/i.test(url.hostname))throw Error('Use a public HTTPS source');return url;}
