function sourceFromInput(value,kind='all',branch='main',folder=''){const url=publicSourceURL(value);if(url.hostname==='github.com'){const parts=url.pathname.split('/').filter(Boolean);if(parts.length<2||!parts.slice(0,2).every(x=>/^[a-z\d_.-]+$/i.test(x)))throw Error('Use a GitHub repository URL');if(parts[2]==='tree'){branch=parts[3]||branch;folder=parts.slice(4).join('/');}if(folder)packagePath(folder);return{id:crypto.randomUUID(),type:'github',name:parts[0]+'/'+parts[1],repo:parts.slice(0,2).join('/'),branch:branch||'main',path:folder,kind};}return{id:crypto.randomUUID(),type:'catalog',name:url.hostname,url:url.href,kind};}
async function githubCatalogue(source){if(!/^[a-z\d_.-]+\/[a-z\d_.-]+$/i.test(source.repo)||typeof source.branch!=='string'||source.branch.length>100)throw Error('Invalid repository');const root=source.path?packagePath(source.path).replace(/\/$/,'')+'/':'',tree=JSON.parse(await marketFetch('https://api.github.com/repos/'+source.repo+'/git/trees/'+encodeURIComponent(source.branch)+'?recursive=1',4*1048576));if(!Array.isArray(tree.tree))throw Error('This repository has no readable tree');if(tree.truncated)throw Error('Repository is too large. Use a package folder or JSON catalog');const manifests=tree.tree.filter(item=>item.type==='blob'&&item.path.startsWith(root)&&item.path.endsWith('manifest.json')&&!item.path.split('/').includes('node_modules')).filter(item=>source.kind!=='all'||/(?:^|\/)(?:community-)?(?:plugins|themes|skills|emojis)\//.test(item.path)).slice(0,150);return mapLimited(manifests,async item=>{const base='https://raw.githubusercontent.com/'+source.repo+'/'+encodeURIComponent(source.branch)+'/'+item.path.slice(0,-'manifest.json'.length),raw=JSON.parse(await marketFetch(base+'manifest.json',65536)),kind=source.kind==='all'?/(?:^|\/)(?:community-)?themes\//.test(item.path)?'theme':/(?:^|\/)skills\//.test(item.path)?'skill':/(?:^|\/)emojis\//.test(item.path)?'emoji':'plugin':source.kind,manifest=kind==='emoji'?{id:String(raw.id||base),name:String(raw.name||'Emoji').slice(0,100),description:String(raw.description||'').slice(0,500),tags:[]}:packageManifest(raw,kind);if(kind==='emoji'){const url=publicSourceURL(new URL(raw.url||packagePath(raw.image||'emoji.png'),base).href).href;return{id:source.id+':emoji:'+manifest.id,kind,manifest,emoji:{id:manifest.id,name:manifest.name,url},source:source.name,sourceId:source.id};}return{id:source.id+':'+kind+':'+manifest.id,kind,manifest,base,source:source.name,sourceId:source.id};});}
async function jsonCatalogue(source){const data=JSON.parse(await marketFetch(source.url)),items=[];if(data.api!==undefined&&data.api!==1)throw Error('Unsupported catalog API');for(const [list,kind]of [['themes','theme'],['plugins','plugin'],['skills','skill'],['emojis','emoji']])for(const item of (Array.isArray(data[list])?data[list]:[]).slice(0,300)){if(source.kind!=='all'&&source.kind!==kind)continue;if(kind==='emoji'){const url=publicSourceURL(item.url).href;items.push({id:source.id+':emoji:'+String(item.id||url),kind,manifest:{id:String(item.id||url),name:String(item.name||'Emoji').slice(0,100),description:String(item.description||'').slice(0,500),tags:[]},emoji:{...item,url},source:source.name,sourceId:source.id});}else{const manifest=packageManifest(item.manifest||item,kind),base=new URL(item.base||kind+'s/'+manifest.id+'/',source.url).href;publicSourceURL(base);items.push({id:source.id+':'+kind+':'+manifest.id,kind,manifest,base:base.endsWith('/')?base:base+'/',source:source.name,sourceId:source.id});}}return items;}
let marketCatalogueJob=null;
async function refreshMarketCatalogue(){if(marketCatalogueJob)return marketCatalogueJob;marketCatalogueJob=loadMarketCatalogue();try{return await marketCatalogueJob;}finally{marketCatalogueJob=null;}}
async function loadMarketCatalogue(){const status=document.querySelector('[data-yappy-market-status]');if(status)status.textContent='Loading source metadata';const results=await Promise.allSettled(cfg.market.sources.map(source=>source.type==='github'?githubCatalogue(source):jsonCatalogue(source)));communityItems=results.flatMap(r=>r.status==='fulfilled'?r.value:[]);marketCatalogueLoaded=true;const errors=results.filter(r=>r.status==='rejected').map(r=>r.reason.message);marketViewRefresh?.();if(errors.length)toast(errors.join('\n'));}
