function marketSourcesPanel(){openPanel('Market sources',(s,close)=>{const list=el('div'),url=input('','https://github.com/owner/repository'),branch=input('main','Branch'),folder=input('','Package folder, optional'),kind=el('select',{'aria-label':'Source content'},...['all','theme','plugin','skill','emoji'].map(v=>el('option',{value:v},v)));url.setAttribute('aria-label','Repository or catalog URL');branch.setAttribute('aria-label','Repository branch');folder.setAttribute('aria-label','Repository folder');const draw=()=>{list.replaceChildren();for(const source of cfg.market.sources)list.append(card(source.name,paragraph(source.type==='github'?source.repo+' on '+source.branch:source.url),button('Remove source',()=>{cfg.market.sources=cfg.market.sources.filter(x=>x.id!==source.id);storage(KEY,cfg);communityItems=communityItems.filter(x=>x.sourceId!==source.id);marketViewRefresh?.();draw();})));};s.append(paragraph('Add a GitHub repository or a JSON catalog with themes, plugins, skills or emojis'),url,field('Content',kind),field('Branch',branch),field('Folder',folder),button('Add source',async()=>{const source=sourceFromInput(url.value,kind.value,branch.value,folder.value);cfg.market.sources.push(source);storage(KEY,cfg);url.value='';draw();await refreshMarketCatalogue();}),list);draw();});}
