function nativeSkillItems(){const seen=new Set();return [...userFeatures().map(x=>[...x,false]),['autoShard','AutoShard','Claim ready shard quests while the Shards panel is open','tools',false],['emojiDiscovery','Emoji Discovery','Search emojis and GIFs from your collection','media',false],['autoedit','AutoEdit','Rules for your outgoing text','messages',false],['history','Edited message log','Browse received edits','messages',false],['keepDeleted','Deleted message log','Keep messages received before deletion','messages',false],...availableLeaks().map(x=>[...x,'Leaks',true]),['nicknames','Nicknames','Names for your friends and servers','native',true]].filter(([key])=>!seen.has(key)&&seen.add(key)).map(([key,name,description,category,native])=>({id:'native:'+key,kind:'skill',native:true,featureKey:key,nativeFlag:!!native,category,manifest:{id:key,name,description,tags:[category,'native'],author:'Yappy'}}));}
