async function loopWallpaperGIF(file){const bytes=new Uint8Array(await file.arrayBuffer());let p=13;if(bytes[10]&128)p+=3*(2**((bytes[10]&7)+1));const loop=new Uint8Array([33,255,11,78,69,84,83,67,65,80,69,50,46,48,3,1,0,0,0]);const out=[bytes.slice(0,p),loop];while(p<bytes.length){const start=p,tag=bytes[p++];if(tag===59){out.push(bytes.slice(start));break;}if(tag===33){const label=bytes[p++];const app=label===255?String.fromCharCode(...bytes.slice(p+1,p+12)):'';while(p<bytes.length){const n=bytes[p++];if(!n)break;p+=n;}if(!['NETSCAPE2.0','ANIMEXTS1.0'].includes(app))out.push(bytes.slice(start,p));}else if(tag===44){const packed=bytes[p+8];p+=9;if(packed&128)p+=3*(2**((packed&7)+1));p++;while(p<bytes.length){const n=bytes[p++];if(!n)break;p+=n;}out.push(bytes.slice(start,p));}else throw Error('Invalid GIF');}return new File(out,file.name,{type:'image/gif',lastModified:file.lastModified});}

