const setupKeys=['accent','background','surface','text','theme','transparency','panelOpacity','wallpaperDim','blur','modalBlur','railLayout','railSize','railNames','unifiedAccent'];
function setupSafe(raw){if(!raw||typeof raw!=='object'||Array.isArray(raw))throw Error('Invalid Yappy setup');const out={};for(const k of setupKeys){const v=raw[k];if(['accent','background','surface','text'].includes(k)){if(typeof v==='string'&&/^#[a-f0-9]{6}$/i.test(v))out[k]=v;}else if(['theme','transparency','railNames','unifiedAccent'].includes(k)){if(typeof v==='boolean')out[k]=v;}else if(k==='railLayout'){if(['horizontal','vertical'].includes(v))out[k]=v;}else if(typeof v==='number'&&Number.isFinite(v)){out[k]=Math.max(k==='panelOpacity'?.2:0,Math.min(k==='railSize'?64:k==='panelOpacity'?1:k==='wallpaperDim'?.85:32,v));}}return out;}
