function setupPreview(settings,size){openPanel('Preview setup',(host,close)=>{const preview=el('div',{style:'border-radius:14px;padding:20px;background:'+(settings.background||'#101014')+';color:'+(settings.text||'#eee')},el('b',{},'Yappy preview'),el('div',{style:'margin-top:12px;padding:14px;border-radius:10px;background:'+(settings.surface||'#17171e')},'A chat message',el('div',{style:'margin-top:8px;color:'+(settings.accent||'#a78bfa')},'Accent colour')));host.append(preview,paragraph('Changes '+Object.keys(settings).join(', ')+'\nMessage size '+size+' bytes\nThemes and layout only'),button('Apply setup',()=>{Object.assign(cfg,settings);saveSettings();close();toast('Setup applied');}));});}
