let horizontalDrag=null,horizontalSuppressClick=false;
function horizontalList(row){const list=row?.parentElement;return list?.matches('.drag-list')&&list.closest('.rail')?list:null;}
function horizontalRows(list){return [...list.children].filter(node=>node.matches('.drag-row[data-drag-id]'));}
