function horizontalDragEnd(e,cancel=false){const d=horizontalDrag;if(!d||e.pointerId!==d.id)return;horizontalDrag=null;d.point.classList.remove('yappy-dragging');document.querySelectorAll('[data-yappy-drop-before],[data-yappy-drop-after]').forEach(n=>{n.removeAttribute('data-yappy-drop-before');n.removeAttribute('data-yappy-drop-after');});if(!d.moving)return;horizontalSuppressClick=true;setTimeout(()=>horizontalSuppressClick=false,300);e.preventDefault();e.stopImmediatePropagation();if(cancel||!d.target||d.target===d.row||!d.row.isConnected)return;const rows=horizontalRows(d.list),ids=rows.map(row=>row.dataset.dragId),from=ids.indexOf(d.row.dataset.dragId);if(from<0)return;ids.splice(from,1);let at=ids.indexOf(d.target.dataset.dragId);if(at<0)return;ids.splice(at+(d.after?1:0),0,d.row.dataset.dragId);const handler=horizontalNativeReorder(d.row);if(!handler){toast('Server order is unavailable');return;}try{Promise.resolve(handler(ids)).catch(error=>toast(error?.message||'Could not save server order'));}catch(error){toast(error?.message||'Could not save server order');}}
